mapper.update:
UPDATE student_schedule 
SET is_available = #{isAvailable} 
WHERE student_id = #{studentId} 
AND day_of_week = #{dayOfWeek} 
AND time_slot = #{timeSlot}

mapper.select:
SELECT id, job_id, day_of_week, time_slot, needed_count, filled_count
FROM merchant_requirement
WHERE job_id = #{jobId}
